import json

def solve():
    houses = 6
    categories = ["name", "car models", "mothers' names", "hobby"]

    values = {
        "name": ["Eric", "Bob", "Peter", "Alice", "Arnold", "Carol"],
        "car models": ["ford f150", "honda civic", "toyota camry", "tesla model 3", "chevrolet silverado", "bmw 3 series"],
        "mothers' names": ["Sarah", "Penny", "Holly", "Aniya", "Kailyn", "Janelle"],
        "hobby": ["photography", "cooking", "knitting", "gardening", "woodworking", "painting"]
    }

    # Helper state structure
    def make_empty_state():
        state = {
            'assignments': {}
        }
        for cat in categories:
            state['assignments'][cat] = {
                'value_to_pos': {v: None for v in values[cat]},
                'pos_to_value': [None for _ in range(houses)]
            }
        return state

    def clone_state(state):
        new_state = {'assignments': {}}
        for cat in categories:
            v2p = dict(state['assignments'][cat]['value_to_pos'])
            p2v = list(state['assignments'][cat]['pos_to_value'])
            new_state['assignments'][cat] = {'value_to_pos': v2p, 'pos_to_value': p2v}
        return new_state

    def pos_of(state, cat, val):
        return state['assignments'][cat]['value_to_pos'][val]

    def value_at(state, cat, pos):
        return state['assignments'][cat]['pos_to_value'][pos]

    def is_pos_available(state, cat, pos, val):
        # In the same category, ensure the position is not already taken by another value
        current = value_at(state, cat, pos)
        return current is None or current == val

    def assign(state, cat, val, pos):
        # Assign value to position in given category
        if not is_pos_available(state, cat, pos, val):
            return False
        # If value already assigned elsewhere, must match pos
        current_pos = pos_of(state, cat, val)
        if current_pos is not None and current_pos != pos:
            return False
        # Also ensure no other value occupies this pos
        current_val = value_at(state, cat, pos)
        if current_val is not None and current_val != val:
            return False
        # Clear previous position if any (should be None by checks)
        state['assignments'][cat]['value_to_pos'][val] = pos
        state['assignments'][cat]['pos_to_value'][pos] = val
        return True

    def unassign(state, cat, val, pos):
        # Unassign value from position
        state['assignments'][cat]['value_to_pos'][val] = None
        state['assignments'][cat]['pos_to_value'][pos] = None

    # Constraints definitions
    fixed_positions = [
        ("car models", "toyota camry", 5),   # Clue 1
        ("mothers' names", "Kailyn", 5),     # Clue 7
    ]

    equalities = [
        ("name", "Carol", "hobby", "photography"),            # Clue 2
        ("car models", "chevrolet silverado", "mothers' names", "Aniya"),  # Clue 3
        ("car models", "ford f150", "mothers' names", "Sarah"),            # Clue 5
        ("car models", "bmw 3 series", "name", "Bob"),        # Clue 6
        ("name", "Eric", "hobby", "gardening"),               # Clue 13
        ("car models", "honda civic", "name", "Arnold"),      # Clue 16
    ]

    not_at = [
        ("car models", "chevrolet silverado", 1),             # Clue 4 (house 2 -> index 1)
    ]

    # Directly left of constraints (adjacent)
    directly_left_of = [
        ("name", "Eric", "hobby", "knitting"),                # Clue 8
        ("mothers' names", "Holly", "hobby", "knitting"),     # Clue 17
    ]

    # Somewhere left of constraints
    left_of = [
        ("hobby", "woodworking", "hobby", "knitting"),        # Clue 14
    ]

    # Somewhere right of constraints
    right_of = [
        ("mothers' names", "Penny", "hobby", "knitting"),     # Clue 10
        ("mothers' names", "Aniya", "car models", "honda civic"),  # Clue 11
        ("name", "Alice", "car models", "ford f150"),         # Clue 12
    ]

    # Exactly one house between constraints (distance of 2)
    distance_two = [
        ("mothers' names", "Sarah", "car models", "toyota camry"),  # Clue 9
        ("mothers' names", "Sarah", "hobby", "cooking"),            # Clue 15
    ]

    # Build helper functions for constraints
    def in_bounds(pos):
        return 0 <= pos < houses

    def check_equalities(state):
        for c1, v1, c2, v2 in equalities:
            p1 = pos_of(state, c1, v1)
            p2 = pos_of(state, c2, v2)
            if p1 is not None and p2 is not None and p1 != p2:
                return False
        return True

    def check_fixed(state):
        for c, v, p in fixed_positions:
            pv = pos_of(state, c, v)
            if pv is not None and pv != p:
                return False
            # also if the position is occupied by a different value in the same category
            occ = value_at(state, c, p)
            if occ is not None and occ != v:
                return False
        return True

    def check_not_at(state):
        for c, v, p in not_at:
            pv = pos_of(state, c, v)
            if pv is not None and pv == p:
                return False
        return True

    def check_directly_left_of(state):
        for c1, v1, c2, v2 in directly_left_of:
            p1 = pos_of(state, c1, v1)
            p2 = pos_of(state, c2, v2)
            if p1 is not None and p1 == houses - 1:
                return False  # cannot be last if must be directly left of someone
            if p2 is not None and p2 == 0:
                return False  # cannot be first if someone must be directly left of you
            if p1 is not None and p2 is not None and p1 + 1 != p2:
                return False
        return True

    def check_left_of(state):
        for c1, v1, c2, v2 in left_of:
            p1 = pos_of(state, c1, v1)
            p2 = pos_of(state, c2, v2)
            if p1 is not None and p2 is not None and not (p1 < p2):
                return False
        return True

    def check_right_of(state):
        for c1, v1, c2, v2 in right_of:
            p1 = pos_of(state, c1, v1)
            p2 = pos_of(state, c2, v2)
            if p1 is not None and p2 is not None and not (p1 > p2):
                return False
        return True

    def check_distance_two(state):
        for c1, v1, c2, v2 in distance_two:
            p1 = pos_of(state, c1, v1)
            p2 = pos_of(state, c2, v2)
            if p1 is not None and p2 is not None and abs(p1 - p2) != 2:
                return False
        return True

    def all_constraints_ok(state):
        return (check_fixed(state) and
                check_equalities(state) and
                check_not_at(state) and
                check_directly_left_of(state) and
                check_left_of(state) and
                check_right_of(state) and
                check_distance_two(state))

    # Domain computation for MRV
    def get_domain(state, cat, val):
        # If already assigned, domain is its current pos
        current_pos = pos_of(state, cat, val)
        if current_pos is not None:
            return [current_pos]

        domain = set(range(houses))

        # Remove positions already taken by other values in the same category
        for pos in range(houses):
            occ = value_at(state, cat, pos)
            if occ is not None and occ != val:
                if pos in domain:
                    domain.remove(pos)

        # Apply fixed positions
        for c, v, p in fixed_positions:
            if cat == c and val == v:
                domain = {p}

        # Apply not_at
        for c, v, p in not_at:
            if cat == c and val == v:
                if p in domain:
                    domain.remove(p)

        # Apply equality constraints: if counterpart assigned, must be same position
        for c1, v1, c2, v2 in equalities:
            if cat == c1 and val == v1:
                p2 = pos_of(state, c2, v2)
                if p2 is not None:
                    domain = {p2} if p2 in domain else set()
            if cat == c2 and val == v2:
                p1 = pos_of(state, c1, v1)
                if p1 is not None:
                    domain = {p1} if p1 in domain else set()

        # Apply directly_left_of constraints
        for c1, v1, c2, v2 in directly_left_of:
            if cat == c1 and val == v1:
                # source cannot be last
                if (houses - 1) in domain:
                    domain.remove(houses - 1)
                pB = pos_of(state, c2, v2)
                if pB is not None:
                    desired = pB - 1
                    if desired in domain:
                        domain = {desired}
                    else:
                        domain = set()
            if cat == c2 and val == v2:
                # target cannot be first
                if 0 in domain:
                    domain.remove(0)
                pA = pos_of(state, c1, v1)
                if pA is not None:
                    desired = pA + 1
                    if desired in domain:
                        domain = {desired}
                    else:
                        domain = set()

        # Apply somewhere left_of constraints
        for c1, v1, c2, v2 in left_of:
            if cat == c1 and val == v1:
                pT = pos_of(state, c2, v2)
                if pT is not None:
                    domain = {d for d in domain if d < pT}
            if cat == c2 and val == v2:
                pS = pos_of(state, c1, v1)
                if pS is not None:
                    domain = {d for d in domain if d > pS}

        # Apply somewhere right_of constraints
        for c1, v1, c2, v2 in right_of:
            if cat == c1 and val == v1:
                pT = pos_of(state, c2, v2)
                if pT is not None:
                    domain = {d for d in domain if d > pT}
            if cat == c2 and val == v2:
                pL = pos_of(state, c1, v1)
                if pL is not None:
                    domain = {d for d in domain if d < pL}

        # Apply distance_two constraints
        for c1, v1, c2, v2 in distance_two:
            if cat == c1 and val == v1:
                p2 = pos_of(state, c2, v2)
                if p2 is not None:
                    candidates = set()
                    if in_bounds(p2 - 2):
                        candidates.add(p2 - 2)
                    if in_bounds(p2 + 2):
                        candidates.add(p2 + 2)
                    domain = domain & candidates
            if cat == c2 and val == v2:
                p1 = pos_of(state, c1, v1)
                if p1 is not None:
                    candidates = set()
                    if in_bounds(p1 - 2):
                        candidates.add(p1 - 2)
                    if in_bounds(p1 + 2):
                        candidates.add(p1 + 2)
                    domain = domain & candidates

        # Additional logical boundary constraints implied by adjacency:
        # Eric directly left of knitting => Eric not last, knitting not first
        if cat == "name" and val == "Eric":
            if (houses - 1) in domain:
                domain.remove(houses - 1)
            pK = pos_of(state, "hobby", "knitting")
            if pK is not None:
                desired = pK - 1
                domain = {desired} if desired in domain else set()
        if cat == "mothers' names" and val == "Holly":
            if (houses - 1) in domain:
                domain.remove(houses - 1)
            pK = pos_of(state, "hobby", "knitting")
            if pK is not None:
                desired = pK - 1
                domain = {desired} if desired in domain else set()
        if cat == "hobby" and val == "knitting":
            if 0 in domain:
                domain.remove(0)
            pE = pos_of(state, "name", "Eric")
            if pE is not None:
                desired = pE + 1
                domain = {desired} if desired in domain else set()
            pH = pos_of(state, "mothers' names", "Holly")
            if pH is not None:
                desired = pH + 1
                domain = {desired} if desired in domain else set()

        # Clue 12 can also restrict Alice if ford f150 is known
        if cat == "name" and val == "Alice":
            pF = pos_of(state, "car models", "ford f150")
            if pF is not None:
                domain = {d for d in domain if d > pF}

        return sorted(domain)

    # Prepare initial state and apply fixed assignments
    initial_state = make_empty_state()
    for c, v, p in fixed_positions:
        if not assign(initial_state, c, v, p):
            raise RuntimeError("Failed to apply fixed positions")

    # Backtracking search with MRV
    def is_complete(state):
        for cat in categories:
            for v in values[cat]:
                if pos_of(state, cat, v) is None:
                    return False
        return True

    def select_unassigned_var(state):
        # MRV: pick the (category, value) pair with smallest domain
        best = None
        best_domain = None
        for cat in categories:
            for v in values[cat]:
                if pos_of(state, cat, v) is None:
                    dom = get_domain(state, cat, v)
                    if best is None or len(dom) < len(best_domain):
                        best = (cat, v)
                        best_domain = dom
                        if len(best_domain) == 0:
                            return best, best_domain
        return best, best_domain

    def backtrack(state):
        if not all_constraints_ok(state):
            return None
        if is_complete(state):
            return state
        (cat, val), domain = select_unassigned_var(state)
        if domain is None or len(domain) == 0:
            return None
        for pos in domain:
            if not is_pos_available(state, cat, pos, val):
                continue
            # assign and recurse
            # We need to work on a cloned state to avoid complex undo logic
            new_state = clone_state(state)
            if not assign(new_state, cat, val, pos):
                continue
            result = backtrack(new_state)
            if result is not None:
                return result
        return None

    solved = backtrack(initial_state)
    if solved is None:
        raise RuntimeError("No solution found")

    # Build output
    header = ["House", "name", "car models", "mothers' names", "hobby"]
    rows = []
    for i in range(houses):
        house_num = str(i + 1)
        name_val = solved['assignments']["name"]["pos_to_value"][i]
        car_val = solved['assignments']["car models"]["pos_to_value"][i]
        mother_val = solved['assignments']["mothers' names"]["pos_to_value"][i]
        hobby_val = solved['assignments']["hobby"]["pos_to_value"][i]
        rows.append([house_num, name_val, car_val, mother_val, hobby_val])

    solution = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return solution

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
